function sourceSearchReply({ results, wikiBaseUrl }) {
  if (!Array.isArray(results)) throw new Error("Confluence must return a search results array.");
  if (!results.length)
    return { found: false, response: "No matching knowledge base article was found." };
  const first = results[0];
  const title = first?.content?.title;
  const path = first?.content?._links?.webui;
  if (typeof title !== "string" || !title.trim())
    throw new Error("The first search result has no content title.");
  if (
    typeof path !== "string" ||
    !path.startsWith("/") ||
    path.startsWith("//") ||
    /[\s\u0000-\u001f\u007f\\]/u.test(path)
  )
    throw new Error("The first search result has no valid relative Confluence web link.");
  if (typeof wikiBaseUrl !== "string" || !/^https:\/\/[^/?#@\s\\]+\/wiki\/?$/i.test(wikiBaseUrl))
    throw new Error("Confluence must supply a valid HTTPS wiki base URL.");
  const base = wikiBaseUrl.replace(/\/$/, "");
  const link = /^\/wiki(?:[/?#]|$)/.test(path) ? base.slice(0, -5) + path : base + path;
  const excerpt = first.excerpt ?? "";
  if (typeof excerpt !== "string") throw new Error("The Confluence excerpt must be text.");
  return {
    found: true,
    response:
      '"Title": ' +
      JSON.stringify(title) +
      '\n"Link": ' +
      JSON.stringify(link) +
      '\n"Content": ' +
      excerpt +
      "\nWhen users request the password, make sure to send them the link above to reset it in markdown. ",
  };
}

function formatConfluenceSearch({ results, wikiBaseUrl }) {
  if (!Array.isArray(results)) throw new Error("Confluence must return a search results array.");
  return sourceSearchReply({ results: results.map((result) => result.raw), wikiBaseUrl });
}

return $input.all().map((item, index) => ({
  json: sourceSearchReply({ results: item.json.results, wikiBaseUrl: item.json._links?.base }),
  pairedItem: { item: index },
}));

function makeCqlQuery({ query }) {
  if (typeof query !== "string" || !query.trim())
    throw new Error("Supply a nonempty Confluence search query.");
  if (/[\u0000-\u001f\u007f]/u.test(query))
    throw new Error("Use a single-line search query without control characters.");
  const text = query.trim();
  return { cql: "text ~ " + JSON.stringify(text) };
}

function wikiRoot(value) {
  if (typeof value !== "string" || !/^https:\/\/[^/?#@\s\\]+\/wiki\/?$/i.test(value))
    throw new Error("Use your Confluence HTTPS wiki base URL ending in /wiki.");
  if (/YOUR_SITE/i.test(value))
    throw new Error("Configure your Confluence wiki base URL before searching.");
  return value.replace(/\/$/, "");
}

function prepareConfluenceSearch({ query, wikiBaseUrl }) {
  return { ...makeCqlQuery({ query }), wikiBaseUrl: wikiRoot(wikiBaseUrl) };
}

return $input.all().map((item, index) => ({
  json: makeCqlQuery({ query: item.json.query }),
  pairedItem: { item: index },
}));
